create table if not exists images(id serial primary key,mime text not null,data bytea not null,created_at timestamptz default now());
create table if not exists users(id serial primary key,name text not null,email text unique not null,password_hash text not null,role text not null default 'cashier',created_at timestamptz default now());
create table if not exists customers(id serial primary key,name text not null,phone text unique not null,password_hash text not null,created_at timestamptz default now());
create table if not exists products(id serial primary key,name text not null,category text not null default 'General',price integer not null check(price>=0),active boolean not null default true);
create table if not exists categories(id serial primary key,name text unique not null,image_id integer references images(id) on delete set null);
create table if not exists orders(id serial primary key,customer text default 'Walk-in',table_no text default '',total integer not null,status text not null default 'open',method text,user_id integer references users(id) on delete set null,created_at timestamptz default now(),paid_at timestamptz);
create table if not exists order_items(id serial primary key,order_id integer not null references orders(id) on delete cascade,product_id integer references products(id) on delete set null,name text not null,price integer not null,qty integer not null);
create table if not exists settings(key text primary key,value text);
create index if not exists orders_status_idx on orders(status,paid_at);
alter table products add column if not exists image_id integer references images(id) on delete set null;
alter table users add column if not exists avatar_id integer references images(id) on delete set null;
alter table customers add column if not exists avatar_id integer references images(id) on delete set null;
alter table orders add column if not exists phone text default '';
alter table orders add column if not exists customer_id integer references customers(id) on delete set null;
alter table orders add column if not exists source text default 'pos';
alter table orders add column if not exists pay_pref text;
alter table orders add column if not exists pay_ref text default '';
alter table orders add column if not exists order_type text default 'dine_in';
alter table orders add column if not exists packing integer default 0;
alter table products add column if not exists available boolean not null default true;
alter table products add column if not exists stock integer;
alter table orders add column if not exists stage text not null default 'received';
alter table products add column if not exists pack boolean not null default true;
create table if not exists offers(id serial primary key,product_id integer not null references products(id) on delete cascade,title text not null default 'Special offer',percent integer not null,start_date date,end_date date,weekdays text default '',active boolean not null default true);
create table if not exists push_subs(id serial primary key,user_id integer references users(id) on delete cascade,endpoint text unique not null,p256dh text not null,auth text not null);
alter table orders add column if not exists momo_fee integer default 0;
alter table orders add column if not exists fulfil text default 'pickup';
alter table orders add column if not exists delivery_fee integer default 0;
alter table orders add column if not exists address text default '';
alter table orders add column if not exists instructions text default '';
create table if not exists chat_messages(id serial primary key,customer_id integer not null references customers(id) on delete cascade,sender text not null,staff_id integer references users(id) on delete set null,body text not null,read boolean not null default false,created_at timestamptz default now());
create index if not exists chat_cust_idx on chat_messages(customer_id,id);
alter table users add column if not exists phone text default '';
alter table orders add column if not exists rider_id integer references users(id) on delete set null;
alter table orders add column if not exists rider_cash integer default 0;
alter table orders add column if not exists cash_settled boolean not null default false;
alter table orders add column if not exists delivered_at timestamptz;
alter table products add column if not exists local boolean not null default false;
alter table order_items add column if not exists sides text default '';
alter table categories add column if not exists pack_fee integer;
